final class NightCustodyChecks {
 static boolean setup,started,done;static int age;static VillagerEntity guard;static net.minecraft.entity.MarkerEntity jail;static Vec3d start;static int jailed;static VillagerEntity blocker;
 static void require(boolean b,String s){if(!b)throw new AssertionError(s);}
 static void register(){if(!Boolean.getBoolean("halloween.nightCustodyTest"))return;ServerTickEvents.END_SERVER_TICK.register(server->{if(done)return;var w=server.getOverworld();if(w.getPlayers().isEmpty())return;var p=w.getPlayers().getFirst();try{if(!setup){for(int x=-3;x<=3;x++)for(int z=-4;z<=8;z++)w.setChunkForced(x,z,true);for(var e:w.getEntitiesByClass(MarkerEntity.class,new Box(-400,0,-400,400,300,400),e->true))e.discard();for(int x=-18;x<=18;x++)for(int z=-35;z<=45;z++){w.setBlockState(new BlockPos(x,119,z),Blocks.STONE.getDefaultState(),Block.NOTIFY_LISTENERS);for(int y=120;y<125;y++)w.setBlockState(new BlockPos(x,y,z),Blocks.AIR.getDefaultState(),Block.NOTIFY_LISTENERS);}jail=EntityType.MARKER.create(w,SpawnReason.EVENT);jail.setPosition(.5,113,20.5);jail.addCommandTag("halloween_jail");jail.addCommandTag("halloween_prison_facing_0");w.spawnEntity(jail);var gate=EntityType.MARKER.create(w,SpawnReason.EVENT);gate.setPosition(.5,120,20.5);gate.addCommandTag("halloween_gate_left");w.spawnEntity(gate);for(int x=-8;x<=8;x++)for(int z=19;z<=99;z++)for(int y=112;y<=116;y++)w.setBlockState(new BlockPos(x,y,z),Blocks.AIR.getDefaultState(),Block.NOTIFY_LISTENERS);VillagePrisons.prepare(w,jail);blocker=EntityType.VILLAGER.create(w,SpawnReason.EVENT);blocker.setAiDisabled(true);blocker.setNoGravity(true);blocker.setPosition(6.95,113,93.5);w.spawnEntity(blocker);guard=EntityType.VILLAGER.create(w,SpawnReason.EVENT);guard.setVillagerData(guard.getVillagerData().withProfession(GuardProfession.ENTRY));guard.addCommandTag("halloween_guard");guard.setPosition(.5,120,-15.5);w.spawnEntity(guard);p.stopRiding();PlayerJustice.clear(p);p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);p.setInvulnerable(true);p.getAbilities().flying=false;p.sendAbilitiesUpdate();p.networkHandler.requestTeleport(.5,120,-17.5,0,0);w.setTimeOfDay(18000);setup=true;return;}
 if(!started){if(++age<30)return;p.addCommandTag("halloween_player_wanted");p.addCommandTag("halloween_player_custody");p.addCommandTag("halloween_player_guard_"+guard.getUuidAsString());guard.addCommandTag("halloween_player_guarding");PlayerJustice.makeLead(w,p,guard);start=guard.getEntityPos();started=true;age=0;}
 age++;if(age%100==0)org.slf4j.LoggerFactory.getLogger("night-custody-test").info("CONVOY age={} guard={} player={} cell={} remand={} ready={}",age,guard.getEntityPos(),p.getEntityPos(),VillagePrisons.assigned(p),p.getCommandTags().contains("halloween_player_remand"),VillagePrisons.ready(w,jail));
 if(p.getCommandTags().contains("halloween_player_remand_inside")){require(guard.getEntityPos().distanceTo(start)>20,"guard really walks from arrest to dungeon");require(!PlayerJustice.leadAttached(w,p,guard),"lead detached in cell");require(VillagePrisons.assigned(p)!=null&&p.squaredDistanceTo(Vec3d.ofBottomCenter(VillagePrisons.assigned(p)))<4,"player actually inside assigned cell: "+p.getEntityPos()+" assigned="+VillagePrisons.assigned(p));require(!p.getCommandTags().contains("halloween_player_sentenced"),"night remand is not a verdict");var cell=VillagePrisons.assigned(p);var bar=cell.add(-2,0,0);require(w.getBlockState(bar).isOf(Blocks.IRON_BARS)&&w.getBlockState(bar.up()).isOf(Blocks.IRON_BARS),"cell door bars really closed");if(++jailed>20){require(!VillagePrisons.ready(w,jail),"completed near room works while far wall is occupied");done=true;org.slf4j.LoggerFactory.getLogger("night-custody-test").info("PASS actual night escort without court marker: guard walked, player followed real leash, entered assigned cell before hearing; lead removed");cStop();}}require(age<1800,"night convoy stalled");
 }catch(Throwable e){done=true;org.slf4j.LoggerFactory.getLogger("night-custody-test").error("FAIL",e);cStop();}});ClientTickEvents.START_CLIENT_TICK.register(c->{if(c.player==null)return;c.options.pauseOnLostFocus=false;c.options.forwardKey.setPressed(false);c.options.backKey.setPressed(false);c.options.sneakKey.setPressed(false);c.options.jumpKey.setPressed(false);if(c.currentScreen instanceof net.minecraft.client.gui.screen.GameMenuScreen)c.setScreen(null);});}
 static void cStop(){net.minecraft.client.MinecraftClient.getInstance().execute(()->net.minecraft.client.MinecraftClient.getInstance().scheduleStop());}
}
